import { getGlobalCliConfig, writeGlobalCliConfig } from '../utils/config.util';
import logger from '../utils/logger.util';

const logout = async (deafen = false) => {
  const prevConfig = getGlobalCliConfig();
  if (!prevConfig?.user?.name) {
    !deafen && logger.log('already logged out');
    return null;
  }

  writeGlobalCliConfig({ ...prevConfig, user: null });
  !deafen && logger.log('logged out successfully');
  return null;
};

export default logout;
